import * as argon2 from 'argon2';

/**
 * OWASP-recommended Argon2id baseline (19 MiB, 2 iterations, 1 lane). The salt
 * is generated by the library and embedded in the PHC string, so only the
 * resulting hash is stored.
 */
export const ARGON2_OPTIONS = Object.freeze({
  type: argon2.argon2id,
  memoryCost: 19456,
  timeCost: 2,
  parallelism: 1,
  hashLength: 32,
} satisfies argon2.HashOptions);

/**
 * Valid Argon2id digest used to keep unknown-email logins roughly as expensive
 * as wrong-password logins. It is not a real account password.
 */
export const DUMMY_PASSWORD_HASH =
  '$argon2id$v=19$m=19456,t=2,p=1$1C4aME+HnP6MUTu0E2Secw$Yav0/kRtNbxKOyJphnCq5QEGpAIg14KmPoiKLlXoKVs';

export async function hashPassword(password: string): Promise<string> {
  return argon2.hash(password, ARGON2_OPTIONS);
}

/** Returns false for malformed digests or library errors instead of leaking. */
export async function verifyPassword(
  passwordHash: string,
  password: string,
): Promise<boolean> {
  try {
    return await argon2.verify(passwordHash, password);
  } catch {
    return false;
  }
}

/** Spends the same verification work for an email that does not exist. */
export async function verifyAgainstDummyPassword(
  password: string,
): Promise<boolean> {
  try {
    await argon2.verify(DUMMY_PASSWORD_HASH, password);
  } catch {
    // The outcome is discarded; the caller always reports invalid credentials.
  }

  return false;
}
